INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('pt0001', 'pt', 'olá', 'hello', 'interj', NULL, NULL, 'Olá, tudo bem?', 'Hello, how are you?', '["core","saudacao"]', 1, NULL, 'basics') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('pt0002', 'pt', 'bom dia', 'good morning', 'phrase', NULL, 'until noon; after that — boa tarde', 'Bom dia! Um café, se faz favor.', 'Good morning! A coffee, please.', '["core","saudacao"]', 2, NULL, 'basics') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('pt0003', 'pt', 'boa tarde', 'good afternoon', 'phrase', NULL, 'from noon until dark', 'Boa tarde, faz favor.', 'Good afternoon, please.', '["core","saudacao"]', 3, NULL, 'basics') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('pt0004', 'pt', 'boa noite', 'good evening / good night', 'phrase', NULL, 'both a greeting and a farewell', 'Boa noite, até amanhã.', 'Good night, see you tomorrow.', '["core","saudacao"]', 4, NULL, 'basics') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('pt0005', 'pt', 'obrigado', 'thank you', 'interj', NULL, 'agrees with the SPEAKER''s gender: men say obrigado, women — obrigada', 'Muito obrigado pela ajuda.', 'Thank you very much for the help.', '["core","cortesia"]', 5, NULL, 'basics') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('pt0006', 'pt', 'de nada', 'you''re welcome', 'phrase', NULL, NULL, '— Obrigado! — De nada.', '— Thanks! — You''re welcome.', '["core","cortesia"]', 6, NULL, 'basics') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('pt0007', 'pt', 'se faz favor', 'please (request)', 'phrase', NULL, 'distinctly European Portuguese; Brazilians say por favor', 'A conta, se faz favor.', 'The bill, please.', '["core","cortesia","pt-pt"]', 7, NULL, 'basics') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('pt0008', 'pt', 'desculpe', 'excuse me / sorry', 'interj', NULL, 'formal; informal — desculpa', 'Desculpe, pode ajudar-me?', 'Excuse me, can you help me?', '["core","cortesia"]', 8, NULL, 'basics') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('pt0009', 'pt', 'com licença', 'excuse me (passing by)', 'phrase', NULL, 'when squeezing past someone, not when apologising', 'Com licença, posso passar?', 'Excuse me, may I pass?', '["core","cortesia"]', 9, NULL, 'basics') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
