INSERT INTO cards (id, course, term, trans, pos, gender, note, ex_t, ex_trans, tags, freq, entry, unit) VALUES ('pt0014', 'pt', 'não percebo', 'I don''t understand', 'phrase', NULL, 'key pt-PT marker: perceber = to understand; Brazilian entender sounds foreign here', 'Desculpe, não percebo.', 'Sorry, I don''t understand.', '["core","sobrevivencia","pt-pt"]', 14, NULL, 'basics') ON CONFLICT(id) DO UPDATE SET course = excluded.course, term = excluded.term, trans = excluded.trans, pos = excluded.pos, gender = excluded.gender, note = excluded.note, ex_t = excluded.ex_t, ex_trans = excluded.ex_trans, tags = excluded.tags, freq = excluded.freq, entry = excluded.entry, unit = excluded.unit;
